"""mpl_toolkits.axes_grid1.axes_divider — axes divider."""


class Divider:
    def __init__(self, fig, pos, horizontal, vertical, aspect=None, anchor='C'):
        self._fig = fig
        self._pos = pos

    def new_locator(self, nx, ny, nx1=None, ny1=None):
        return lambda ax, renderer: None

    def append_size(self, position, size):
        pass


class SubplotDivider(Divider):
    def __init__(self, fig, *args, horizontal=None, vertical=None, aspect=None, anchor='C'):
        super().__init__(fig, None, horizontal or [], vertical or [], aspect, anchor)


class AxesDivider:
    def __init__(self, axes):
        self._axes = axes

    def append_axes(self, position, size, pad=None, add_to_figure=True, **kwargs):
        return self._axes

    def new_horizontal(self, size, pad=None, pack_start=False, **kwargs):
        return None

    def new_vertical(self, size, pad=None, pack_start=False, **kwargs):
        return None


def make_axes_locatable(axes):
    return AxesDivider(axes)


class Size:
    class Fixed:
        def __init__(self, fixed_size, fraction=None):
            self.fixed_size = fixed_size

    class Scaled:
        def __init__(self, scalable_size):
            self.scalable_size = scalable_size

    class AxesX:
        def __init__(self, axes, aspect=1, ref_ax=None):
            pass

    class AxesY:
        def __init__(self, axes, aspect=1, ref_ax=None):
            pass

    class Fraction:
        def __init__(self, fraction, ref_size=None):
            self.fraction = fraction

    class Padded:
        def __init__(self, size, pad):
            pass

    @staticmethod
    def from_any(size, fraction_ref=None):
        if isinstance(size, (int, float)):
            return Size.Fixed(size)
        return Size.Fixed(0)


# ─── Added: missing divider classes/helpers ─────────────────────────


class AxesLocator:
    """Resolves a divider position into final axes coordinates at draw
    time. Mirrors upstream's class of the same name."""

    def __init__(self, axes_divider, nx, ny, nx1=None, ny1=None):
        self.divider = axes_divider
        self.nx, self.ny = nx, ny
        self.nx1, self.ny1 = nx1, ny1

    def __call__(self, axes, renderer=None):
        return [0.1, 0.1, 0.8, 0.8]

    def get_subplotspec(self):
        return getattr(self.divider, '_subplotspec', None)


class HBoxDivider:
    """A divider that splits its area horizontally. Subclasses upstream's
    :class:`Divider`; the shim is a minimal placeholder."""

    def __init__(self, fig=None, horizontal=None, vertical=None,
                 anchor='C'):
        self.fig = fig
        self.horizontal = horizontal or []
        self.vertical = vertical or []
        self.anchor = anchor

    def new_locator(self, nx, ny=0, nx1=None, ny1=None):
        return AxesLocator(self, nx, ny, nx1, ny1)


class VBoxDivider(HBoxDivider):
    """A divider that splits its area vertically. Inherits the
    HBoxDivider surface but exposes a different conceptual name."""
    pass


def make_axes_area_auto_adjustable(ax, use_axes=None, pad=0.1,
                                    adjust_dirs=None):
    """Adjust ``ax``'s position so it doesn't overlap with the axes in
    ``use_axes``. The plotly backend autosizes — no-op."""
    return None
